{
  "target_engine": "Godot 4.4",
  "initial_state": "Idle",
  "parameters": {
    "moving": "bool",
    "grounded": "bool",
    "jump_pressed": "bool",
    "vertical_velocity": "float"
  },
  "states": [
    "Idle",
    "Run",
    "Jump",
    "Fall"
  ],
  "transitions": [
    {
      "from": "Idle",
      "to": "Jump",
      "when": "grounded and jump_pressed",
      "priority": 100
    },
    {
      "from": "Run",
      "to": "Jump",
      "when": "grounded and jump_pressed",
      "priority": 100
    },
    {
      "from": "Idle",
      "to": "Fall",
      "when": "not grounded and vertical_velocity > 0",
      "priority": 90
    },
    {
      "from": "Run",
      "to": "Fall",
      "when": "not grounded and vertical_velocity > 0",
      "priority": 90
    },
    {
      "from": "Idle",
      "to": "Run",
      "when": "grounded and moving and not jump_pressed",
      "priority": 10
    },
    {
      "from": "Run",
      "to": "Idle",
      "when": "grounded and not moving and not jump_pressed",
      "priority": 10
    },
    {
      "from": "Jump",
      "to": "Fall",
      "when": "not grounded and vertical_velocity >= 0",
      "priority": 80
    },
    {
      "from": "Fall",
      "to": "Run",
      "when": "grounded and moving",
      "priority": 70
    },
    {
      "from": "Fall",
      "to": "Idle",
      "when": "grounded and not moving",
      "priority": 70
    }
  ],
  "evaluation": "Select a single eligible outgoing edge with maximum priority per physics tick; ties are an error. Travel API pathing is not this priority evaluator.",
  "coordinate_system": "Godot 2D positive Y down",
  "integration": "Authoring contract only, not a directly importable Godot resource; implement evaluator or map guards to AnimationTree parameters."
}
